export default async function ({ folderId }, ctx) {
  if (typeof folderId !== "string" || !folderId.trim() || folderId.startsWith("YOUR_"))
    throw Error("Configure a Drive folder ID");
  const escaped = folderId.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
  const files = [],
    seen = new Set();
  let token;
  do {
    const page = await ctx.actions.call("googledrive.files.list", {
      q: `'${escaped}' in parents`,
      pageSize: 100 - files.length,
      orderBy: "modifiedTime",
      corpora: "allDrives",
      includeItemsFromAllDrives: true,
      supportsAllDrives: true,
      spaces: "drive",
      ...(token ? { pageToken: token } : {}),
    });
    if (!Array.isArray(page?.files)) throw Error("Invalid Drive listing");
    files.push(...page.files);
    token = page.nextPageToken;
    if (token) {
      if (typeof token !== "string" || seen.has(token)) throw Error("Invalid Drive page token");
      seen.add(token);
    }
  } while (token && files.length < 100);
  const links = [];
  for (const f of files.slice(0, 100)) {
    if (typeof f?.id !== "string" || !f.id || typeof f.name !== "string")
      throw Error("Invalid Drive file");
    const r = await ctx.actions.call("googledrive.permissions.create", {
      fileId: f.id,
      type: "anyone",
      role: "reader",
      supportsAllDrives: true,
    });
    if (typeof r?.id !== "string" || !r.id) throw Error("Permission not confirmed");
    links.push({
      name: f.name,
      link: `https://drive.google.com/uc?id=${encodeURIComponent(f.id)}&export=download&confirm=t`,
    });
  }
  return { links };
}
